var i=`0733-kanda`;var t=`world-0733`;var a=`CF`;var o=`central-africa`;var s=4;var r=58;var l={en:`Kanda`,ua:`Канда`};var d={en:`Kanda is a Central African Republic classic prepared with ground beef, ground egusi, yellow onion, garlic. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Канда, страва кухні країни Центральноафриканська Республіка зі складниками: яловичий фарш, мелене егусі, жовта цибуля, часник. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:14,i:[[`ground-beef`,550,`g`],[`ground-egusi`,160,`g`],[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`table-salt`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 17 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 17 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:17,i:[[`red-palm-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 24 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 24 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:24,i:[[`tomato`,300,`g`],[`water`,450,`ml`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var u={slug:i,id:t,country:`CF`,region:o,servings:4,minutes:58,title:l,text:d,steps:g};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,i as slug,g as steps,d as text,l as title};